{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "In this plan, is the quantity of product purchased in a given month allowed to be sold in that same month, or must purchased units wait until the following month before they can be sold?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy choice regarding the timing of sales relative to purchases."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units can be purchased in a month (for example, a supplier's monthly supply cap), or can we purchase any non-negative quantity at the given monthly price?"
  ],
  "rationale": "The response asks a single clarification question regarding the existence of a monthly purchase limit versus unlimited purchasing."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units can be sold in a given month (for example, a monthly demand cap), or can we sell any non-negative quantity up to what we have in stock at the given monthly price?"
  ],
  "rationale": "The response asks a single clarification question regarding the upper bound of monthly sales, framed as a choice between a cap and stock availability."
}

